def calculate_tax(amount: Decimal, region: str) -> Decimal:
    rate = TAX_RATES.get(region, Decimal("0"))
    return (amount * rate).quantize(Decimal("0.01"))

def kira_cukai(jumlah: Decimal, wilayah: str) -> Decimal:
    kadar = KADAR_CUKAI.get(wilayah, Decimal("0"))
    return (jumlah * kadar).quantize(Decimal("0.01"))

def hitung_pajak(jumlah: Decimal, wilayah: str) -> Decimal:
    tarif = TARIF_PAJAK.get(wilayah, Decimal("0"))
    return (jumlah * tarif).quantize(Decimal("0.01"))
